namespace Finora.Shared;public sealed record Result(bool IsSuccess,string? Error=null){public static Result Success()=>new(true);public static Result Failure(string error)=>new(false,error);}public sealed record Result<T>(T? Value,bool IsSuccess,string? Error=null){public static Result<T> Success(T value)=>new(value,true);public static Result<T> Failure(string error)=>new(default,false,error);}
